// Get the raw input text dynamically from the previous node
const rawHTML = $json.text; // Adjust to match the actual field name in your input

// Use regex to clean up the unwanted ```html prefix and trailing ``` if present
const cleanedHTML = rawHTML
    .replace(/^```html\s*/, "") // Removes the ```html prefix and any leading whitespace
    .replace(/```$/, "") // Removes the trailing ```
    .trim(); // Cleans up any remaining whitespace

// Return the cleaned HTML for further processing
return [
  {
    html: cleanedHTML, // Cleaned and formatted HTML
  },
];
